def find_pluses(g):
    H,W=len(g),len(g[0]); comp=[]; inc=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] not in (0,3):
                arms=[g[i-1][j] if i else 0, g[i+1][j] if i<H-1 else 0,
                      g[i][j-1] if j else 0, g[i][j+1] if j<W-1 else 0]
                (comp if arms==[3,3,3,3] else inc).append((i,j,g[i][j]))
    return comp,inc

def transform(grid):
    H,W=len(grid),len(grid[0])
    comp,inc=find_pluses(grid)
    out=[row[:] for row in grid]
    inc_cols={j for _,j,_ in inc}
    blocked3={(i,j) for i in range(H) for j in range(W) if grid[i][j]==3}
    own3={ (i+cj,3) for _ in [0] for i in range(1) }
    def paint(cells, color, horiz, stopper):
        for (i,j) in cells:
            if grid[i][j]==3: continue  # keep 3s
            if horiz and j in inc_cols: continue  # hole at incomplete center column
            out[i][j]=color
    for (r,c,col) in comp:
        # column ray: blocked by other pluses' 3s
        def other3(i,j):
            return grid[i][j]==3 and not any(abs(i-r)<=1 and abs(j-c)<=1 for (rr,cc,_) in [(r,c,col)])
        # vertical
        for i in range(r-1,-1,-1):
            if other3(i,c): break
            if grid[i][c]!=3: out[i][c]=col
        for i in range(r+1,H):
            if other3(i,c): break
            if grid[i][c]!=3: out[i][c]=col
        # horizontal
        for j in range(c-1,-1,-1):
            if other3(r,j): break
            if grid[r][j]!=3 and j not in inc_cols: out[r][j]=col
        for j in range(c+1,W):
            if other3(r,j): break
            if grid[r][j]!=3 and j not in inc_cols: out[r][j]=col
    return out

